import React from "react";
import "./Preview.css";
import Navbar from "./Navbar";

function Preview({ data, onEdit, onConfirm }) {
  return (
    <>
      <Navbar title="Review Setup" />

      <div className="preview-page">
        <div className="preview-card">

          {/* HEADER */}
          <div className="preview-header">
            <h1>Review Your Setup</h1>
            <p>Please confirm your details before proceeding</p>
          </div>

          {/* CONTENT */}
          <div className="preview-content">

            {/* INCOME */}
            <div className="preview-row">
              <span className="label">Income Type</span>
              <span className="value">
                {data.income || "Not selected"}
              </span>
            </div>

            {/* CATEGORIES */}
            <div className="preview-row">
              <span className="label">Selected Categories</span>
              <div className="value tags">
                {(data.categories || []).map((cat, i) => (
                  <span key={i} className="tag">{cat}</span>
                ))}
              </div>
            </div>

            {/* BUDGET LIMITS */}
            <div className="preview-row column">
              <span className="label">Budget Limits</span>

              <div className="limits-box">
                {Object.entries(data.limits || {}).map(([key, val]) => (
                  <div key={key} className="limit-row">
                    <span>{key}</span>
                    <span>₹{val}</span>
                  </div>
                ))}
              </div>
            </div>

          </div>

          {/* ACTIONS */}
          <div className="preview-actions">
            <button className="edit-btn" onClick={onEdit}>
              Edit Details
            </button>

            <button className="confirm-btn" onClick={onConfirm}>
              Continue to Dashboard
            </button>
          </div>

        </div>
      </div>
    </>
  );
}

export default Preview;
